<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Control de papeleta</title><style>body{margin:0;background:#f1f5f9;font-family:Arial;color:#14213d}.wrap{max-width:560px;margin:auto;padding:22px}.card{background:#fff;border-radius:18px;padding:22px;margin:14px 0;box-shadow:0 4px 18px #0001}button{width:100%;padding:15px;border:0;border-radius:12px;background:#075985;color:#fff;font-size:16px;font-weight:bold}canvas{border:2px dashed #94a3b8;border-radius:12px;width:100%;height:180px;touch-action:none}input{box-sizing:border-box;width:100%;margin:7px 0 13px;padding:12px;border:1px solid #cbd5e1;border-radius:9px}</style></head><body><main class="wrap"><h2>Control de salida</h2><div class="card"><b>Papeleta N.° {{ $papeleta->numero_papeleta }}</b><p>{{ $papeleta->employee?->full_name }} · {{ $papeleta->reason?->nombre }}</p><p>Salida: {{ $papeleta->salida_real_at?->format('d/m/Y H:i') ?? 'Pendiente' }}<br>Retorno: {{ $papeleta->retorno_real_at?->format('d/m/Y H:i') ?? 'Pendiente' }}</p></div>@if(session('ok'))<div class="card" style="color:#166534">{{ session('ok') }}</div>@endif @if(!$papeleta->salida_real_at)<form method="post" action="{{ route('papeletas.qr.salida',$token) }}" class="card">@csrf<button>Marcar salida</button></form>@elseif(!$papeleta->retorno_real_at)<form method="post" action="{{ route('papeletas.qr.retorno',$token) }}" class="card">@csrf<button>Marcar retorno</button></form>@endif @if($papeleta->reason?->tipo === 'comision' && !$papeleta->destino_firmado_at)<form method="post" action="{{ route('papeletas.qr.destino',$token) }}" class="card">@csrf<label>Nombre del responsable de destino</label><input required name="nombre"><label>Cargo</label><input required name="cargo"><label>Firma táctil</label><canvas id="pad"></canvas><input type="hidden" required name="firma" id="firma"><p><button type="submit">Registrar constancia de destino</button></p></form><script>const c=document.querySelector('#pad'),x=c.getContext('2d');let down=false;c.width=c.offsetWidth*2;c.height=360;x.scale(2,2);x.lineWidth=2;x.lineCap='round';function pos(e){let r=c.getBoundingClientRect(),p=e.touches?e.touches[0]:e;return{x:p.clientX-r.left,y:p.clientY-r.top}}function start(e){down=true;let p=pos(e);x.beginPath();x.moveTo(p.x,p.y);e.preventDefault()}function move(e){if(!down)return;let p=pos(e);x.lineTo(p.x,p.y);x.stroke();e.preventDefault()}c.addEventListener('pointerdown',start);c.addEventListener('pointermove',move);['pointerup','pointerleave'].forEach(e=>c.addEventListener(e,()=>down=false));document.querySelector('form[action*="destino"]').addEventListener('submit',()=>document.querySelector('#firma').value=c.toDataURL('image/png'));</script>@elseif($papeleta->destino_firmado_at)<div class="card" style="color:#166534">Constancia de destino: {{ $papeleta->destino_firmante_nombre }} · {{ $papeleta->destino_firmante_cargo }}<br>{{ $papeleta->destino_firmado_at->format('d/m/Y H:i') }}</div>@endif</main></body></html>
